import java.util.*;

class ValidationSummary {
    static String validationSummary(int[] left, int[] right) {
        List<Integer> merged = new ArrayList<>();
        int leftIndex = 0;
        int rightIndex = 0;
        while (leftIndex < left.length && rightIndex < right.length) {
            if (left[leftIndex] <= right[rightIndex]) {
                merged.add(left[leftIndex++]);
            } else {
                merged.add(right[rightIndex++]);
            }
        }
        while (leftIndex < left.length) merged.add(left[leftIndex++]);
        while (rightIndex < right.length) merged.add(right[rightIndex++]);
        return merged.stream().map(String::valueOf).reduce((a, b) -> a + "," + b).orElse("");
    }
}
